"""Native exact ownership of the declared physical network's incidences.

Every two-ended original Street is consumed once, either by its compound or
by a corridor. A single-ended approach may remain explicitly outside this
inspection selection. This guard does not claim full OSM coverage.
"""
import bpy
from . import curved_junction_nodes as boundary

c = boundary.c


def _compare(g, a, b, operation='EQUAL'):
    node = g.node('FunctionNodeCompare')
    node.data_type = 'INT'
    node.operation = operation
    for key, value in (('A', a), ('B', b)):
        socket = next(s for s in node.inputs if s.name == key and s.type == 'INT')
        g.bind(value, socket)
    return c.V(g, node.outputs['Result'])


def _total(g, value, group):
    node = g.node('GeometryNodeAccumulateField')
    node.data_type = 'INT'
    node.domain = 'POINT'
    g.bind(value, node.inputs['Value'])
    g.bind(group, node.inputs['Group ID'])
    return c.V(g, node.outputs['Total'])


def _all(g, geometry, field):
    return c.choose(g, _compare(g, c._count(g, geometry), 0, 'GREATER_THAN'),
                    c._stat(g, geometry, field), 1.)


def _exists(g, names):
    result = 1.
    for name in names:
        node = g.node('GeometryNodeInputNamedAttribute')
        node.data_type = 'INT'
        node.inputs['Name'].default_value = name
        result = result * c.V(g, node.outputs['Exists'])
    return result


def build(*,port_paths=False):
    name = 'Prochitecture Streets / Original surface ownership v1'
    if port_paths:name += ' / Original Section spans v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Approaches', 'Corridors', 'External Approaches'):
        g.socket(key, 'NodeSocketGeometry')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    g.socket('Diagnostics', 'NodeSocketGeometry', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    original = inp.outputs['Approaches']
    corridors = inp.outputs['Corridors']
    external = inp.outputs['External Approaches']
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    street = c.named(g, 'st_cj_street_id', 'INT')
    group = c.named(g, 'st_cj_span_index', 'INT') if port_paths else street
    reverse = c.named(g, 'st_cj_reverse', 'INT')
    absorbed = c.named(g, 'st_cn_absorbed', 'BOOLEAN')

    # Group by integer semantic identities, without float sorting or a nested
    # loop over every pair of Streets. Original records lead the joined table.
    rows = original
    for key, value in (
        ('st_co_incidence_count', _total(g, 1, group)),
        ('st_co_reverse_count', _total(g, reverse, group)),
        ('st_co_absorbed_count', _total(g, absorbed, group)),
        ('_co_mouth', index), ('_co_use', 0),
    ):
        rows = c._store(g, rows, key, value, 'INT')
    uses = [rows]
    table_valid = 1.
    for table, prefix, ends in (
        (corridors, 'st_cs_', ('start_index', 'end_index')),
        (external, 'st_ca_', ('start_index',)),
    ):
        valid = _exists(g, [prefix + 'street_id', *(prefix + key for key in ends)])
        if port_paths:valid=valid*_exists(g,(prefix+'span_index',))
        for key in ends:
            at = c.named(g, prefix + key, 'INT')
            valid = valid * _compare(g, at, 0, 'GREATER_EQUAL')
            valid = valid * _compare(g, at, c._count(g, rows), 'LESS_THAN')
            valid = valid * _compare(g, c.named(g, prefix + 'street_id', 'INT'),
                                    c._read(g, rows, 'st_cj_street_id', at, 'INT'))
            if port_paths:
                valid=valid*_compare(g,c.named(g,prefix+'span_index','INT'),c._read(g,rows,'st_cj_span_index',at,'INT'))
            valid = valid * _compare(g, c._read(g, rows, 'st_co_incidence_count', at, 'INT'), len(ends))
            valid = valid * (1. - c._read(g, rows, 'st_cn_absorbed', at, 'BOOLEAN'))
            if len(ends) == 2:
                valid = valid * _compare(g, c._read(g, rows, 'st_cj_reverse', at, 'INT'),
                                        0 if key == 'start_index' else 1)
            consumer = c._store(g, table, '_co_mouth', at, 'INT')
            consumer = c._store(g, consumer, '_co_use', 1, 'INT')
            uses.append(consumer)
        table_valid = table_valid * _all(g, table, valid)
    combined = boundary._join(g, *uses)
    combined = c._store(g, combined, 'st_co_consumer_count',
                        _total(g, c.named(g, '_co_use', 'INT'), c.named(g, '_co_mouth', 'INT')), 'INT')
    use = c._read(g, combined, 'st_co_consumer_count', index, 'INT')
    rows = c._store(g, rows, 'st_co_consumer_count', use, 'INT')
    count = c.named(g, 'st_co_incidence_count', 'INT')
    internal = _compare(g, count, 2)
    paired = _compare(g, c.named(g, 'st_co_reverse_count', 'INT'), 1)
    expected_absorbed = c.choose(g, absorbed, 2, 0, 'INT')
    valid = _exists(g, ('st_cj_street_id', 'st_cj_reverse'))
    valid = valid * _compare(g, street, 0, 'GREATER_EQUAL')
    valid = valid * (_compare(g, reverse, 0) + _compare(g, reverse, 1))
    valid = valid * _compare(g, count, 1, 'GREATER_EQUAL') * _compare(g, count, 2, 'LESS_EQUAL')
    valid = valid * c.choose(g, internal, paired, 1. - absorbed)
    valid = valid * _compare(g, c.named(g, 'st_co_absorbed_count', 'INT'), expected_absorbed)
    valid = valid * c.choose(g, internal,
        _compare(g, c.named(g, 'st_co_consumer_count', 'INT'), c.choose(g, absorbed, 0, 1, 'INT')),
        _compare(g, c.named(g, 'st_co_consumer_count', 'INT'), 1, 'LESS_EQUAL'))
    if port_paths:
        role=c.named(g,'st_cj_span_role','INT')
        valid=valid*_exists(g,('st_cj_span_index','st_cj_span_role','st_pp_span'))
        valid=valid*_compare(g,group,c.named(g,'st_pp_span','INT'))*_compare(g,group,0,'GREATER_EQUAL')
        # Roles: corridor=1, free approach=2, absorbed=3, pending remote=4.
        # The latter is an explicit scope boundary, never a generated free end.
        expected=c.choose(g,internal,c.choose(g,absorbed,3,1,'INT'),c.choose(g,_compare(g,role,2),2,4,'INT'),'INT')
        valid=valid*_compare(g,role,expected)
        valid=valid*c.choose(g,internal,1.,_compare(g,c.named(g,'st_co_consumer_count','INT'),c.choose(g,_compare(g,role,2),1,0,'INT')))
        for field in ('street_id','section_id','junction_id','connector_id','reverse'):
            valid=valid*_compare(g,c.named(g,'st_cj_'+field,'INT'),c.named(g,'st_pp_'+field,'INT'))
    rows = c._store(g, rows, 'st_co_valid', valid, 'BOOLEAN')
    good = table_valid * _all(g, rows, c.named(g, 'st_co_valid', 'BOOLEAN'))
    out = g.node('NodeGroupOutput')
    g.bind(good, out.inputs['Valid'])
    g.bind(rows, out.inputs['Diagnostics'])
    return g.g
